originalFirstStyle:
/* Single-window plugin browser: light solid overlay, no blur/animated shadows. */

.plugin-target{font-size:10px;color:#81b5c7;letter-spacing:normal;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.plugin-close{background:transparent;border:0;color:#aeb7bc;font-size:23px;width:24px;height:26px;line-height:24px}
.plugin-close:hover{color:#fff;background:#4b5052}
.plugin-results{flex:1;min-height:0;overflow-y:auto;background:#25282a}
.plugin-name{font-size:11px;color:#e0e3e4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.plugin-meta{font-size:9px;color:#899da6;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.plugin-labels{display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex:none;font-size:9px;color:#87969c}
.plugin-pill{color:#a6b6bb;border:1px solid #495156;padding:1px 4px;border-radius:2px}
.plugin-pill.problem{color:#da9990;border-color:#85554f}
.plugin-flag{width:21px;height:22px;background:transparent;border:0;color:#777e82;font-size:15px;flex:none;padding:0}
.plugin-flag.starred{color:#d3b86b}
.plugin-flag:hover{background:#465055;color:#e6e9eb}
.plugin-empty{padding:20px 12px;text-align:center;color:#88979b;font-size:11px}
.plugin-footer{height:36px;flex:none;display:flex;align-items:center;padding:0 7px;gap:6px;border-top:1px solid #181a1b;font-size:10px}
.plugin-footer span{flex:1;color:#a0afb6}
.plugin-footer button{background:#393d40;border:1px solid #4f575b;color:#bcc6ca;border-radius:2px;padding:4px 6px;font-size:10px}
.plugin-footer button:disabled{color:#657175;opacity:1;cursor:not-allowed}
.plugin-disclaimer{padding:7px 9px;flex:none;color:#c2ac85;background:#35322d;font-size:9px;line-height:1.3}
@media(max-width:940px){}


.more-tools{margin-left:auto;position:relative;flex:none}
.more-tools summary{list-style:none;cursor:pointer;white-space:nowrap;user-select:none}
.more-tools summary::-webkit-details-marker{display:none}
.more-tools[open] summary{color:#d7e8eb;background:#405159}
.more-tools-panel{position:absolute;z-index:35;right:0;top:calc(100% + 6px);width:278px;max-height:min(460px,calc(100vh - 138px));overflow:auto;background:#303436;border:1px solid #596167;box-shadow:0 4px 12px #111b;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px;padding:9px}
.more-tools-panel .tool,.more-tools-panel .toolbar-select{width:100%;max-width:none;min-width:0;margin:0}
.more-tools-caption{grid-column:1 / -1;font-size:9px;color:#8fa1a8;letter-spacing:.08em;padding:5px 0 0;border-bottom:1px solid #434c50}
@media(max-width:900px){.command-bar{padding:0 5px;gap:4px}.command-bar .toolbar-label{display:none}.command-bar .tool{padding:4px 6px}.command-bar .toolbar-select{max-width:86px}.command-bar .sep{margin:0 1px}}

