.plugin-target{font-size:10px;color:#81b5c7;letter-spacing:normal;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.plugin-close{background:transparent;border:0;color:#aeb7bc;font-size:23px;width:24px;height:26px;line-height:24px}
.plugin-close:hover{color:#fff;background:#4b5052}
.plugin-results{flex:1;min-height:0;overflow-y:auto;background:#25282a}
.plugin-name{font-size:11px;color:#e0e3e4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.plugin-meta{font-size:9px;color:#899da6;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.plugin-labels{display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex:none;font-size:9px;color:#87969c}
.plugin-pill{color:#a6b6bb;border:1px solid #495156;padding:1px 4px;border-radius:2px}
.plugin-pill.problem{color:#da9990;border-color:#85554f}
.plugin-flag{width:21px;height:22px;background:transparent;border:0;color:#777e82;font-size:15px;flex:none;padding:0}
.plugin-flag.starred{color:#d3b86b}
.plugin-flag:hover{background:#465055;color:#e6e9eb}
.plugin-empty{padding:20px 12px;text-align:center;color:#88979b;font-size:11px}
.plugin-footer{height:36px;flex:none;display:flex;align-items:center;padding:0 7px;gap:6px;border-top:1px solid #181a1b;font-size:10px}
.plugin-footer span{flex:1;color:#a0afb6}
.plugin-footer button{background:#393d40;border:1px solid #4f575b;color:#bcc6ca;border-radius:2px;padding:4px 6px;font-size:10px}
.plugin-footer button:disabled{color:#657175;opacity:1;cursor:not-allowed}
.plugin-disclaimer{padding:7px 9px;flex:none;color:#c2ac85;background:#35322d;font-size:9px;line-height:1.3}
@media(max-width:940px){}



.console-body.plugin-open #viewport{margin-right:0!important}
.plugin-browser[hidden],.fast-picker[hidden]{display:none!important}
.plugin-scan-settings{padding:7px 10px;flex:none;display:flex;flex-direction:column;gap:5px;border-top:1px solid #35505d;background:#172630}
.plugin-scan-settings .scan-title{font-size:10px;color:#a6c5d4}
.scan-paths{display:flex;flex-direction:column;gap:3px;max-height:58px;overflow:auto}
.scan-path{display:flex;gap:7px;min-width:0;font-size:10px;align-items:center}
.scan-path>span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.scan-path small{color:#89c1cf}.scan-path button{background:transparent;border:0}
.scan-add{display:flex;gap:5px}.scan-add input{flex:1;min-width:0;height:25px;padding:0 5px;color:#e3f0f5;background:#091922;border:1px solid #40616f}.scan-add button{font-size:10px}
.scan-status{font-size:10px;color:#a8bdc8}
.fast-picker{position:absolute;z-index:100;left:24px;top:110px;width:302px;max-width:calc(100% - 40px);background:#172a34;border:1px solid #587e8e;border-radius:5px;box-shadow:0 10px 25px #000b;overflow:hidden}
.fast-head{display:flex;align-items:center;justify-content:space-between;gap:7px;height:34px;padding:0 9px;background:#203944;border-bottom:1px solid #395e6b;font-weight:600}
.fast-head span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fast-head button{background:transparent;border:0;font-size:20px;color:#ddf1f5}
#fastSearch{display:block;width:calc(100% - 14px);height:30px;margin:7px;padding:0 8px;background:#061820;border:1px solid #547486;border-radius:3px}
.fast-results{min-height:58px;max-height:270px;display:flex;flex-direction:column;gap:2px;overflow:auto;padding:3px 6px 6px}
.fast-effect{width:100%;min-height:29px;padding:5px 7px;display:flex;gap:6px;align-items:center;text-align:left;background:#213844;border:1px solid #305365}
.fast-effect:hover,.fast-effect:focus-visible{background:#365d6b;border-color:#83c8d4}
.fast-effect-title{flex:1;min-width:0;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;color:#a8eac5}
.fast-effect-kind{color:#a5bfc8;font-size:9px}.fast-star{color:#e9c771}.fast-empty{padding:15px;color:#9eafb7}
.fast-foot{height:32px;display:flex;gap:7px;align-items:center;padding:0 8px;border-top:1px solid #355363;color:#91acb8;font-size:9px}
.fast-foot button{margin-left:auto;border:0;background:transparent;color:#85d7f1}
